def chain_follows_chain(chain):
    chain_list = list(chain)
    chain_list.sort()
    result = []
    for token in chain_list:
        if not result or result[-1] != token:
            result.append(token)
    return ','.join(result)

# Example usage:
# print(chain_follows_chain((bbb, ccc)))  # Output: 'aaa, bbb, ccc, ddd'
